(function(){
'use strict';
const E=window.FlowerEngine,$=s=>document.querySelector(s),clone=x=>JSON.parse(JSON.stringify(x));
let state=E.initial(),renderer,toastTimer,autoTimer=null,tourTimer=null,tourIndex=-1,tourPaused=false,tourSaved=null,sourceTab='culture',lastChapter=-1;
const chapters=[['00','先靠近一朵花'],['01','一片布'],['02','层层成花'],['03','花回到背上'],['04','留一份心意'],['05','花有来处']];
const nextLabels=['靠近一朵花','让布片相遇','看见完整构成','把心意留下','回望来处','重新开始'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4400);}
const audio={ctx:null,master:null,pad:null,on:false,timer:null,
 start(){if(this.on)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('unsupported');this.ctx=this.ctx||new AC();this.ctx.resume();this.master=this.ctx.createGain();this.master.gain.value=.16;this.master.connect(this.ctx.destination);this.pad=[];for(const [i,f]of [146.83,220,293.66].entries()){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.025/(i+1);o.connect(g).connect(this.master);o.start();this.pad.push(o);}this.on=true;}catch{toast('当前浏览器暂不能启用声音，仍可完整体验。');state.sound=false;}},
 stop(){this.pad?.forEach(o=>{try{o.stop();}catch{}});this.pad=[];this.on=false;},
 touch(){if(!this.on||!this.ctx)return;const t=this.ctx.currentTime,buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*.13,this.ctx.sampleRate),a=buffer.getChannelData(0),r=E.seeded(77+state.placed.length);for(let i=0;i<a.length;i++)a[i]=(r()*2-1)*Math.pow(1-i/a.length,2);const src=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();src.buffer=buffer;f.type='lowpass';f.frequency.value=900;g.gain.setValueAtTime(.18,t);g.gain.exponentialRampToValueAtTime(.001,t+.13);src.connect(f).connect(g).connect(this.master);src.start();}
};
function progress(){return `<div class="dots" aria-label="已放置${state.placed.length}片，共24片">${E.pieces.map(p=>`<i class="${state.placed.includes(p.id)?'done':p.id===state.selected?'selected':''}"></i>`).join('')}</div><div class="progress-meta"><b>${String(state.placed.length).padStart(2,'0')}</b> / 24 &nbsp;片已相遇</div>`;}
function controls(){return `<div class="stack-control"><div class="button-row"><button class="solid" data-action="place" ${state.placed.length===24?'disabled':''}>放入当前一片 <span>↗</span></button><button class="secondary" data-action="auto">${autoTimer?'停止叠放':'自动叠放'}</button></div><div class="tiny-actions"><button class="quiet" data-action="undo" ${!state.placed.length?'disabled':''}>← 撤销一片</button><button class="quiet" data-action="layers">${state.reveal===24?'逐层拆看':'恢复叠放'}</button><button class="quiet" data-action="clear-stack">清空重叠</button></div>${state.reveal!==24?`<label class="control-label" for="reveal">查看层级 <output id="reveal-value">${state.reveal} / 24</output></label><input class="range" id="reveal" type="range" min="0" max="24" value="${state.reveal}" aria-label="查看层级">`:''}</div>`;}
function copyContent(){switch(state.chapter){
case 0:return `<span class="eyebrow">AN INTERACTIVE TEXTILE STORY / 2026</span><p class="chapter-small">苗族背带的层叠记忆</p><h1 class="hero-title">背上的<em>花</em></h1><p class="subtitle">一片布，如何成为一份祝愿。</p><p class="intro">先从一朵花靠近。<br>看见折痕，叠放一片布，<br>再让目光慢慢回到生活。</p><button class="solid" data-action="next">开始靠近 <span>↗</span></button><p class="little">以贵州台江苗族背带资料为研究切口<br>一件关于材料、照料与心意的当代数字叙事</p>`;
case 1:return `<span class="eyebrow">01 / THE FIRST FOLD</span><h1>一片布，<br>有了<em>方向。</em></h1><p class="intro">拖动折叠进度，观察同一片布的边缘与阴影。<br>从展开到叠合，形状在眼前发生。</p><label class="control-label" for="fold">原创折片示意 <output id="fold-value">${Math.round(state.fold*100)}%</output></label><input class="range" type="range" id="fold" min="0" max="100" value="${state.fold*100}" aria-label="折叠进度"><div class="button-row"><button class="secondary" data-action="unfold">展开布片</button><button class="solid" data-action="fold">折起这一片 ↗</button></div><div class="instruction">光掠过边缘，<br>你也看见了布片之间的距离。</div><button class="text-link" data-action="source-craft">这段动作从何而来 ↗</button><p class="little">屏幕中的几何折叠是本作品的艺术示意，<br>不等同于真实工艺的完整教学。</p>`;
case 2:return `<span class="eyebrow">02 / ONE LAYER AT A TIME</span><h1>一层一层，<br><em>花才出现。</em></h1><p class="intro">将当前布片拖到虚线位置，<br>或点击“放入当前一片”。<br>每一次覆盖，都留下一点关系。</p>${progress()}${controls()}<p class="little">24片为本作品的原创构图设定。<br>可以拆开回看，再让它们重新相遇。</p>`;
case 3:return `<span class="eyebrow">03 / FROM PATTERN TO LIFE</span><h1>花，回到<br><em>背上。</em></h1><p class="intro">从一个折角退远，<br>看见局部怎样成为整体。<br>再想起，布面也曾属于生活里的照料。</p><div class="instruction">三个尺度，同一个位置。<br>找到暗朱红折片 P07，<br>微观与整体在这里相连。</div><label class="control-label" for="angle">轻转布面 <output id="angle-value">${state.angle}°</output></label><input class="range" type="range" id="angle" min="-12" max="12" value="${state.angle}" aria-label="布面角度"><button class="text-link" data-action="source-craft">看资料，辨认创作 ↗</button><p class="little">画面为原创艺术造型与当代生活意象，<br>并非馆藏复刻或历史纪实。</p>`;
case 4:return `<span class="eyebrow">04 / A WISH OF YOUR OWN</span><h1>把一份<em>心意，</em><br>轻轻留下。</h1><p class="intro">选择一个当代主题，让边缘的节奏回应你。<br>中央构成保持原样，心意属于此刻。</p><div class="wish-options" aria-label="当代祝愿主题">${['安稳','陪伴','出发'].map(w=>`<button data-wish="${w}" aria-pressed="${state.wish===w}">${w}</button>`).join('')}</div><label class="wish-label" for="message">写给你惦念的人 <span id="message-count">${state.message.length} / 48</span></label><textarea class="wish-text" id="message" maxlength="48" placeholder="愿……">${esc(state.message)}</textarea><div class="button-row" style="margin-top:20px"><button class="solid" data-action="export">带走这份心意 <span>↓</span></button></div><p class="little">三个主题是本作品的当代创作选项，<br>不代表传统纹样的固定释义。短句仅保留于当前页面。</p>`;
case 5:return `<span class="eyebrow">05 / EVERY FLOWER HAS A ROOT</span><h1>花有来处，<br><em>心意有归。</em></h1><p class="intro">走过整幅画面，再看最初的一片布。<br>你是否愿意，为那些细小的动作，<br>多停留一会儿？</p><p class="final-line">一片布的来处，<br>一份心意的去处。</p><div class="button-row"><button class="solid" data-action="export">留存当前作品 ↓</button><button class="text-link" data-action="sources">资料与创作说明 ↗</button></div><div class="credits-mini"><div><b>文化研究</b>具体对象 · 可追溯资料</div><div><b>当代创作</b>原创构图 · 数字演绎</div></div><p class="little">此作品保留来源与创作的边界。<br>重新开始前，可先下载你的作品卡。</p>`;
}}
function render(){document.body.dataset.chapter=state.chapter;document.body.classList.toggle('reduced',state.reduced);$('#copy').innerHTML=copyContent();$('#copy').classList.remove('copy-enter');if(lastChapter!==state.chapter){void $('#copy').offsetWidth;$('#copy').classList.add('copy-enter');lastChapter=state.chapter;}$('#chapter-nav').innerHTML=chapters.map(([n,t],i)=>`<button data-chapter="${i}" class="${state.chapter===i?'active':''}" aria-label="${t}" ${state.chapter===i?'aria-current="step"':''}>${n}<span>${t}</span></button>`).join('');$('#chapter-count').textContent=(state.chapter===0?'序':String(state.chapter).padStart(2,'0'))+' / 06';$('#next').innerHTML=nextLabels[state.chapter]+' <span>↗</span>';$('#prev').disabled=state.chapter===0;$('#sound').setAttribute('aria-pressed',state.sound);$('#sound span').textContent=state.sound?'开':'关';$('#motion').setAttribute('aria-pressed',state.reduced);$('#motion').textContent=state.reduced?'动态已减少':'减少动态';$('#scale-controls').innerHTML=[0,3,4,5].includes(state.chapter)?[['macro','纤维微观'],['pattern','局部构成'],['whole','完整布面']].map(([v,t])=>`<button data-scale="${v}" aria-pressed="${state.scale===v}">${t}</button>`).join('')+`<button data-action="toggle-composition" class="composition-toggle">${state.composition==='design'?'看我的叠放':'看完整设计'}</button>`:'';$('#art-caption').innerHTML=state.chapter===1?'同一块布片 · <b>P07</b>':state.chapter===2?'原创层叠构成 · 拖拽 / 点击 / 键盘操作':(state.composition==='design'?'完整设计参考 · <b>非馆藏复刻</b>':'我的叠放 '+state.placed.length+' / 24 · <b>非馆藏复刻</b>');$('#bottom-note').textContent=['从材料靠近，让观看慢一点。','屏幕时间不换算真实手工劳动。','每一片的次序，只属于这件原创构图。','资料支持的事实，与今天的艺术想象各有位置。','你的短句不上传，刷新前请下载留存。','图案有来处，表达有边界。'][state.chapter];}
function go(i,{scroll=true}={}){if(!Number.isInteger(i)||i<0||i>5)return;stopAuto();state.chapter=i;if(i===2)state.composition='own';if(i!==2)state.reveal=24;state.angle=0;state.scale=i===2?'pattern':'whole';render();if(scroll)window.scrollTo({top:0,behavior:state.reduced?'instant':'smooth'});}
function put(id=state.selected){if(state.placed.includes(id))return;E.place(state,id);renderer.markPlaced(id);audio.touch();render();if(state.placed.length===24)toast('24片已相遇。可以逐层回看，也可以继续看见整体。');}
function stopAuto(){clearInterval(autoTimer);autoTimer=null;}
function startAuto(){if(autoTimer){stopAuto();render();return;}if(state.placed.length===24){toast('已经完成叠放，可以逐层回看。');return;}autoTimer=setInterval(()=>{const p=E.pieces.find(p=>!state.placed.includes(p.id));if(!p){stopAuto();render();return;}put(p.id);if(state.placed.length===24){stopAuto();render();}},state.reduced?100:440);render();}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportCard(){try{const card=renderer.renderCard(state);card.toBlob(blob=>{if(!blob){toast('作品卡生成失败，请稍后重试。');return;}download(blob,'背上的花_愿'+state.wish+'.png');toast('作品卡已生成，请在浏览器下载位置选择保存。');},'image/png');}catch{toast('当前环境无法导出图片，可先使用截图留存。');}}
const sourceContents={culture:`<div class="source-block"><span class="source-type">S01 / OBJECT-BASED RESEARCH</span><h3>从一件有资料的背孩带开始</h3><div class="source-meta"><span>资料对象 <b>退堆绣鱼鸟纹背孩带</b></span><span>记录地域 <b>贵州台江</b></span><span>民族标注 <b>苗族</b></span><span>记录年代 <b>20世纪80年代</b></span></div><p>中央民族大学民族博物馆介绍了这件背孩带及色布小片叠压构图的方式。本作品据此研究材料关系与层叠表达。</p><a href="https://bwg.muc.edu.cn/info/1021/1137.htm" target="_blank" rel="noopener noreferrer">查看博物馆原始资料 ↗</a></div><div class="source-warning">公开文字没有提供完整尺寸、针路、每片顺序或全部纹样含义。作品采用原创几何与配色，不将屏幕步骤称为藏品精确复原或传统工艺完整教学。</div><div class="source-block"><span class="source-type">S02 / CONTEXT, NOT A COMPOSITE</span><h3>不同对象，保留各自的来处</h3><p>其他背带资料用于理解对象差异，不将其年代、地域、针法或寓意拼接到本作品的参考对象。</p><a href="https://lanmama.lib.hku.hk/items/show/19" target="_blank" rel="noopener noreferrer">香港大学图书馆专题资料 ↗</a></div>`,design:`<div class="source-block"><span class="source-type">CONTEMPORARY ARTISTIC INTERPRETATION</span><h3>哪些是本作品自己的设计？</h3><p>24片的几何位置、抽象鱼鸟启发构成、靛黑与朱红配色、P07识别点、三个尺度的镜头关系，以及“安稳 / 陪伴 / 出发”的边缘节奏，均属于本作品的当代创作设定，不称传统固定纹样与释义。</p><p>布片以程序绘制材质、厚度和叠压阴影；背景为AI辅助生成的原创织物及当代照料意象。生活画面中的人物为虚构，不是传承人、历史人物或采访记录。成品未使用馆藏页面照片。</p></div><div class="source-block"><h3>这份表达，怎样与资料相连？</h3><p>资料提供具体对象与材料线索，原创构图将“片—层—整体”的关系组织成一次可操作观看。基础层叠技法、拖拽、动画与导出均不宣称首创；作品的设计贡献需要通过整体表达来判断。</p></div><div class="source-warning">屏幕停留、完成布片数量与声音节奏是交互设计，不代表真实工艺工时、技能认证或传统仪式。</div>`,usage:`<div class="source-block"><h3>怎样体验</h3><p>可以逐章进入，也可以用左侧章节跳转。叠放章节支持拖拽与点击按钮；键盘 Tab 可到达入口，画面获得焦点后按 Enter 可放入当前布片。查看三个尺度不会清空叠放。可显式切换完整设计参考与我的叠放，作品卡按当前模式导出。</p><p>自动导览使用独立演示状态，结束后恢复开始前的作品。刷新页面会丢失本次操作和短句；请先导出作品卡。当前作品不上传个人输入。</p></div><div class="source-block"><h3>声音与动态</h3><p>声音由程序合成的环境音与布料风格拟音组成，是原创声音设计，非传统音乐采录。声音需主动开启；可随时关闭。减少动态可停用漂浮与过渡。</p></div><div class="source-block"><h3>创作与AI说明</h3><p>当前代码、美术构图、图像生成与文案由AI助手协助形成。完整工具记录、来源与学生实际工作应随参赛材料如实说明；没有发生的调研、审校和用户试用不作为既有成果。</p></div>`};
function renderSources(){const tabs=[['culture','文化依据'],['design','原创与演绎'],['usage','体验与制作']];$('#source-tabs').innerHTML=tabs.map(([v,t])=>`<button data-source-tab="${v}" class="${sourceTab===v?'active':''}">${t}</button>`).join('');$('#source-content').innerHTML=sourceContents[sourceTab];}
function openSources(tab='culture'){sourceTab=tab;renderSources();if(!$('#source-dialog').open)$('#source-dialog').showModal();}
function closeSources(){if($('#source-dialog').open)$('#source-dialog').close();}
const tours=[
 {c:0,t:'01 / 从一朵花开始',d:'一个具体对象，三个观看尺度。先看见完整的原创艺术构成。',f:()=>{state.composition='design';}},
 {c:1,t:'02 / 先看一片布',d:'同一块暗朱红布，保留折叠前后的连续关系。',f:()=>{state.fold=0;}},
 {c:1,t:'03 / 让折痕出现',d:'拖动进度，让布面折向自己；这是原创几何示意。',f:()=>{state.fold=1;}},
 {c:2,t:'04 / 让布片相遇',d:'开始叠放。目标轮廓帮助定位，也提供按钮与键盘等效操作。',f:()=>{state.placed=[];state.selected='p01';}},
 {c:2,t:'05 / 一片覆盖另一片',d:'叠放来自同一构图数据。层间的影子让覆盖关系可见。',f:()=>{state.placed=E.pieces.slice(0,8).map(p=>p.id);state.selected='p09';}},
 {c:2,t:'06 / 逐层回看',d:'把已完成构成拆开观看，保留进度，查看片与片的关系。',f:()=>{E.finish(state);state.reveal=12;}},
 {c:2,t:'07 / 一层一层，花才出现',d:'24片为原创设计设定，完整构成在此相遇。',f:()=>{E.finish(state);}},
 {c:3,t:'08 / 同一个折角',d:'在微观里找到P07；图案与材料来自同一程序模型。',f:()=>{state.scale='macro';}},
 {c:3,t:'09 / 花回到整体',d:'退远后仍能找到同一折片。生活画面是当代艺术意象。',f:()=>{state.scale='whole';}},
 {c:4,t:'10 / 留下一份心意',d:'当代的主题改变边缘节奏，中央研究启发构成保持不变。',f:()=>{state.wish='陪伴';state.message='愿每一次出发，都有人惦念。';}},
 {c:4,t:'11 / 带走此刻的回应',d:'切换“出发”，可导出当前构成与本人短句。',f:()=>{state.wish='出发';state.message='愿前路有光，也有归处。';}},
 {c:5,t:'12 / 花有来处',d:'回到最初的一片布；资料、原创与演绎都留下清楚的边界。',f:()=>{}}
];
function scheduleTour(){clearTimeout(tourTimer);if(!tourPaused)tourTimer=setTimeout(()=>showTour(tourIndex+1),11000);}
function showTour(i){if(i<0||i>=tours.length){endTour();return;}closeSources();tourIndex=i;const t=tours[i];go(t.c,{scroll:true});t.f();render();$('#tourbar').hidden=false;document.body.classList.add('touring');$('#tour-title').textContent=t.t;$('#tour-copy').textContent=t.d;$('#tour-count').textContent=(i+1)+' / '+tours.length;$('#tour-pause').textContent=tourPaused?'继续':'暂停';scheduleTour();}
function startTour(){if(tourIndex>=0){endTour();return;}stopAuto();tourSaved=clone(state);tourPaused=false;toast('导览使用独立演示，结束后恢复你的作品。');showTour(0);}
function endTour(){clearTimeout(tourTimer);tourIndex=-1;$('#tourbar').hidden=true;document.body.classList.remove('touring');if(tourSaved){const sound=state.sound;state=tourSaved;state.sound=sound;tourSaved=null;render();}}
function action(a){if(a==='toggle-composition'){state.composition=state.composition==='design'?'own':'design';render();}if(a==='next'){if(state.chapter===5)$('#reset-dialog').showModal();else go(state.chapter+1);}if(a==='place')put();if(a==='fold'||a==='unfold'){state.fold=a==='fold'?1:0;audio.touch();render();}if(a==='undo'){stopAuto();E.undo(state);render();}if(a==='auto')startAuto();if(a==='clear-stack'){stopAuto();state.placed=[];state.selected='p01';state.reveal=24;render();}if(a==='layers'){state.reveal=state.reveal===24?12:24;render();}if(a==='export')exportCard();if(a==='sources'||a==='source-craft')openSources();if(a==='close')closeSources();if(a==='close-reset')$('#reset-dialog').close();if(a==='confirm-reset'){const sound=state.sound,reduced=state.reduced;state=E.initial();state.sound=sound;state.reduced=reduced;$('#reset-dialog').close();render();}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action)action(b.dataset.action);if(b.dataset.chapter!==undefined){endTour();go(Number(b.dataset.chapter));}if(b.dataset.scale){state.scale=b.dataset.scale;render();}if(b.dataset.wish){state.wish=b.dataset.wish;audio.touch();render();}if(b.dataset.sourceTab){sourceTab=b.dataset.sourceTab;renderSources();}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='fold'){state.fold=Number(el.value)/100;$('#fold-value').textContent=el.value+'%';}if(el.id==='angle'){state.angle=Number(el.value);$('#angle-value').textContent=el.value+'°';}if(el.id==='reveal'){state.reveal=Number(el.value);$('#reveal-value').textContent=el.value+' / 24';}if(el.id==='message'){state.message=el.value.slice(0,48);$('#message-count').textContent=state.message.length+' / 48';}});
$('#next').onclick=()=>action('next');$('#prev').onclick=()=>go(state.chapter-1);$('#sources').onclick=()=>openSources();$('#tour').onclick=startTour;$('#sound').onclick=()=>{state.sound=!state.sound;if(state.sound)audio.start();else audio.stop();$('#sound').setAttribute('aria-pressed',state.sound);$('#sound span').textContent=state.sound?'开':'关';};$('#motion').onclick=()=>{state.reduced=!state.reduced;render();};$('#tour-prev').onclick=()=>showTour(Math.max(0,tourIndex-1));$('#tour-next').onclick=()=>showTour(tourIndex+1);$('#tour-pause').onclick=()=>{tourPaused=!tourPaused;$('#tour-pause').textContent=tourPaused?'继续':'暂停';scheduleTour();};$('#tour-end').onclick=endTour;
document.querySelector('.wordmark').onclick=e=>{e.preventDefault();endTour();go(0);};
render();renderer=new ClothRenderer($('#art'),()=>state);
let pointer=null;
$('#art').addEventListener('pointerdown',e=>{if(state.chapter!==2||state.placed.length===24)return;stopAuto();const [x,y]=renderer.localPoint(e.clientX,e.clientY);pointer={x,y,startX:e.clientX,startY:e.clientY,id:state.selected};renderer.drag={id:state.selected,x,y};$('#art').setPointerCapture(e.pointerId);});
$('#art').addEventListener('pointermove',e=>{if(!pointer)return;const [x,y]=renderer.localPoint(e.clientX,e.clientY);renderer.drag={id:pointer.id,x,y};});
$('#art').addEventListener('pointerup',e=>{if(!pointer)return;const [x,y]=renderer.localPoint(e.clientX,e.clientY),p=E.pieces.find(p=>p.id===pointer.id),dist=Math.hypot(x-p.centroid[0],y-p.centroid[1]);if(dist<53)put(pointer.id);else toast('靠近虚线位置放下，也可以使用“放入当前一片”。');pointer=null;renderer.drag=null;});
$('#art').addEventListener('pointercancel',()=>{pointer=null;renderer.drag=null;});
$('#art').addEventListener('keydown',e=>{if(state.chapter===2&&(e.key==='Enter'||e.key===' ')){e.preventDefault();put();}});
if(matchMedia('(prefers-reduced-motion: reduce)').matches){state.reduced=true;render();}
window.addEventListener('pagehide',()=>audio.stop());
window.FlowerApp={getState:()=>clone(state),goChapter:go,setScale:v=>{if(['macro','pattern','whole'].includes(v)){state.scale=v;render();}},setFold:v=>{state.fold=Math.max(0,Math.min(1,v));render();},place:put,complete:()=>{E.finish(state);render();},startTour,endTour,goTourStep:i=>{if(!tourSaved)tourSaved=clone(state);tourPaused=true;showTour(i);},pauseTour:()=>{tourPaused=true;scheduleTour();$('#tour-pause').textContent='继续';},openSources,closeSources,exportCard,setWish:(wish,message)=>{if(!['安稳','陪伴','出发'].includes(wish))throw Error('未知主题');state.wish=wish;state.message=String(message).slice(0,48);render();},target:id=>renderer.target(id),reset:()=>{stopAuto();endTour();state=E.initial();render();}};
})();
